    FILTER_HISTORYVectorOffset FILTER_HISTORY: Offset = Offset(),
    RESIDUAL_RMS: Double = 0.0,
    TRACE_IDOffset TRACE_ID: Offset = Offset(),
    ATTESTATIONOffset ATTESTATION: Offset = Offset()
  ) -> Offset {
    let __start = ODR.startODR(&fbb)
    ODR.add(RUN_ID: RUN_ID, &fbb)
    ODR.add(STARTED_AT: STARTED_AT, &fbb)
    ODR.add(COMPLETED_AT: COMPLETED_AT, &fbb)
    ODR.add(CONFIGURATION: CONFIGURATION, &fbb)
    ODR.add(CONVERGENCE_REASON: CONVERGENCE_REASON, &fbb)
    ODR.addVectorOf(ITERATIONS: ITERATIONS, &fbb)
    ODR.addVectorOf(EDITED_OBSERVATIONS: EDITED_OBSERVATIONS, &fbb)
    ODR.addVectorOf(ESTIMATED_PARAMETERS: ESTIMATED_PARAMETERS, &fbb)
    ODR.add(ESTIMATED_EPOCH_STATE: ESTIMATED_EPOCH_STATE, &fbb)
    ODR.add(COVARIANCE_DIMENSION: COVARIANCE_DIMENSION, &fbb)
    ODR.addVectorOf(STATE_COVARIANCE: STATE_COVARIANCE, &fbb)
    ODR.add(OCM_CONTENT_ID: OCM_CONTENT_ID, &fbb)
    ODR.addVectorOf(FILTER_HISTORY: FILTER_HISTORY, &fbb)
    ODR.add(RESIDUAL_RMS: RESIDUAL_RMS, &fbb)
    ODR.add(TRACE_ID: TRACE_ID, &fbb)
    ODR.add(ATTESTATION: ATTESTATION, &fbb)
    return ODR.endODR(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.RUN_ID, fieldName: "RUN_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.STARTED_AT, fieldName: "STARTED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.COMPLETED_AT, fieldName: "COMPLETED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CONFIGURATION, fieldName: "CONFIGURATION", required: false, type: ForwardOffset<ODRSolverConfiguration>.self)
    try _v.visit(field: VT.CONVERGENCE_REASON, fieldName: "CONVERGENCE_REASON", required: false, type: odrConvergenceReason.self)
    try _v.visit(field: VT.ITERATIONS, fieldName: "ITERATIONS", required: false, type: ForwardOffset<Vector<ForwardOffset<ODRIterationStatistics>, ODRIterationStatistics>>.self)
    try _v.visit(field: VT.EDITED_OBSERVATIONS, fieldName: "EDITED_OBSERVATIONS", required: false, type: ForwardOffset<Vector<ForwardOffset<ODREditedObservation>, ODREditedObservation>>.self)
    try _v.visit(field: VT.ESTIMATED_PARAMETERS, fieldName: "ESTIMATED_PARAMETERS", required: false, type: ForwardOffset<Vector<ForwardOffset<ODREstimatedParameter>, ODREstimatedParameter>>.self)
    try _v.visit(field: VT.ESTIMATED_EPOCH_STATE, fieldName: "ESTIMATED_EPOCH_STATE", required: false, type: ForwardOffset<FRMStateVector>.self)
    try _v.visit(field: VT.COVARIANCE_DIMENSION, fieldName: "COVARIANCE_DIMENSION", required: false, type: UInt32.self)
    try _v.visit(field: VT.STATE_COVARIANCE, fieldName: "STATE_COVARIANCE", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.OCM_CONTENT_ID, fieldName: "OCM_CONTENT_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FILTER_HISTORY, fieldName: "FILTER_HISTORY", required: false, type: ForwardOffset<Vector<ForwardOffset<ODRFilterEpoch>, ODRFilterEpoch>>.self)
    try _v.visit(field: VT.RESIDUAL_RMS, fieldName: "RESIDUAL_RMS", required: false, type: Double.self)
    try _v.visit(field: VT.TRACE_ID, fieldName: "TRACE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ATTESTATION, fieldName: "ATTESTATION", required: false, type: ForwardOffset<ODRAttestation>.self)
    _v.finish()
  }
}
